def first_true(lo, hi, predicate):
    # finds smallest x in [lo, hi) where predicate(x) is True
    while lo < hi:
        mid = (lo + hi) // 2
        if predicate(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

